import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { SectionLabel } from "@/shared/ui/layout/SectionLabel";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";
import { Chip } from "@/shared/ui/data/Chip";
import { Code } from "@/shared/ui/data/Code";

// Preview-only stand-in for `useAppStore((s) => s.skills)` (app-internal, unresolvable here) — same
// shape/sample the promoted `personaspanel` uses for consistency.
const SAMPLE_SKILLS = [{ id: "s1", name: "schema-design" }, { id: "s2", name: "api-testing" }];
const SAMPLE_PERSONA = {
  id: "p1", name: "Builder", blurb: "Implements features end to end.", role: "worker",
  responsibilities: ["Ship the assigned issue", "Write tests"],
  startPrompt: "You are a builder agent. Pick up the next ready issue and implement it.",
  model: "claude-sonnet-5", skills: ["s1"],
};

export function PersonaSummary({ persona = SAMPLE_PERSONA, flat = false }) {
  const skills = SAMPLE_SKILLS;
  const skillNames = persona.skills.map((id) => skills.find((sk) => sk.id === id)?.name ?? id);
  const body = (
    <Stack gap={8}>
        {persona.blurb && (
          <Text as="div" mono size={10} tone="muted" style={{ lineHeight: 1.5 }}>{persona.blurb}</Text>
        )}

        <Row gap={8} wrap align="center">
          <SectionLabel size={9.5}>model</SectionLabel>
          <Text as="span" mono size={9.5} tone={persona.model ? "accent" : "dim"}>
            {persona.model || "session default"}
          </Text>
        </Row>

        <Box>
          <SectionLabel size={9.5} style={{ marginBottom: 5 }}>
            skills · {skillNames.length}
          </SectionLabel>
          {skillNames.length === 0 ? (
            <Text as="div" mono size={9.5} tone="dim">none attached</Text>
          ) : (
            <Row gap={5} wrap>
              {skillNames.map((name, i) => (
                <Chip key={persona.skills[i]}>{name}</Chip>
              ))}
            </Row>
          )}
        </Box>

        <details>
          <summary className="mono" style={{ cursor: "pointer", fontSize: 10, color: "var(--fg-dim)", userSelect: "none" }}>
            Start prompt
          </summary>
          {persona.startPrompt ? (
            <Code style={{ marginTop: 6 }}>{persona.startPrompt}</Code>
          ) : (
            <Text as="div" mono size={9.5} tone="dim" style={{ marginTop: 6, lineHeight: 1.5 }}>
              No start prompt — falls back to the {persona.role} role's own kickoff assembly at launch.
            </Text>
          )}
        </details>
    </Stack>
  );
  if (flat) return body;
  return (
    <Box bg="var(--bg-panel)" radius={5} pad={[9, 10]} style={{ marginTop: 8, border: "1px solid var(--border-soft)" }}>
      {body}
    </Box>
  );
}
